import { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import api from '../../utils/api';
import { formatDate, toDateInput } from '../../utils/utils';

const SERVICE_TYPES = [
    'Coleta de Inservíveis',
    'Coleta de Animais Mortos',
    'Manutenção de Vias Rurais',
    'Coleta de Galhos',
    'Manutenção de Praças',
    'Manutenção de Escolas Estaduais',
    'Prestação de Serviço às Demais Secretarias',
    'Caminhão Pipa',
];

const SECRETARIAS = [
    'Paço Municipal',
    'Tiro de Guerra',
    'SAMA- Secretaria Municipal de Agricultura e Meio Ambiente',
    'SECOM- Secretaria Municipal de Comunicação',
    'SECULT- Secretaria Municipal de Cultura',
    'SECETUR- Secretaria Municipal de Desenvolvimento Econômico e Turismo',
    'SEJEL- Secretaria Municipal de Esportes',
    'SEMADS- Secretaria Municipal de Assistência e Desenvolvimento Social',
    'SEMIT- Secretaria Municipal de Tecnologia e Inovação',
    'SMA- Secretaria Municipal de Administração',
    'SME- Secretaria Municipal de Educação',
    'SMF- Secretaria Municipal da Fazenda',
    'SMO- Secretaria Municipal de Obras',
    'SMPDU- Secretaria Municipal de Planejamento e Desenvolvimento Urbano',
    'SMS- Secretaria Municipal de Saúde',
    'SMSU- Secretaria Municipal de Serviços Urbanos',
];

const FIELDS_SCHEMA = {
    'Coleta de Inservíveis': ['nomeCidadao', 'enderecoColeta', 'funcionarioResponsavel', 'tipoMaterial', 'observacoes', 'dataSla', 'status', 'dataTrabalho'],
    'Coleta de Animais Mortos': ['nomeCidadao', 'enderecoColeta', 'funcionarioResponsavel', 'porteAnimal', 'observacoes', 'dataSla', 'status', 'dataTrabalho'],
    'Manutenção de Vias Rurais': ['nomePropriedade', 'enderecoUpa', 'funcionarioResponsavel', 'tipoServico', 'observacoes', 'dataSla', 'status', 'dataTrabalho', 'ocorrencia'],
    'Coleta de Galhos': ['nomeCidadao', 'enderecoColeta', 'funcionarioResponsavel', 'observacoes', 'dataSla', 'status', 'dataTrabalho'],
    'Manutenção de Praças': ['endereco', 'funcionarioResponsavel', 'tipoServico', 'observacoes', 'dataSla', 'status', 'dataTrabalho', 'ocorrencia'],
    'Manutenção de Escolas Estaduais': ['nomeSolicitante', 'endereco', 'funcionarioResponsavel', 'tipoMaterial', 'observacoes', 'dataSla', 'status', 'dataTrabalho', 'ocorrencia'],
    'Prestação de Serviço às Demais Secretarias': ['secretaria', 'departamento', 'funcionarioResponsavel', 'tipoServico', 'observacoes', 'dataSla', 'status', 'dataTrabalho', 'ocorrencia'],
    'Caminhão Pipa': ['secretaria', 'departamento', 'funcionarioResponsavel', 'tipoServico', 'observacoes', 'dataSla', 'status', 'dataTrabalho', 'ocorrencia'],
};

const FIELD_LABELS = {
    nomeCidadao: 'Nome do cidadão',
    nomeSolicitante: 'Nome do solicitante',
    nomePropriedade: 'Nome da propriedade',
    endereco: 'Endereço',
    enderecoColeta: 'Endereço da coleta',
    enderecoUpa: 'Endereço / UPA',
    funcionarioResponsavel: 'Funcionário responsável',
    tipoMaterial: 'Tipo de material',
    tipoServico: 'Tipo de serviço',
    porteAnimal: 'Porte do animal',
    secretaria: 'Secretaria',
    departamento: 'Departamento',
    dataSla: 'Prazo Limite',
    status: 'Status / Data',
    observacoes: 'Observações',
    ocorrencia: 'Ocorrência',
};

const addressFieldForType = (serviceType) => {
    if (serviceType === 'Manutenção de Vias Rurais') return 'enderecoUpa';
    if (serviceType === 'Manutenção de Praças' || serviceType === 'Manutenção de Escolas Estaduais') return 'endereco';
    return 'enderecoColeta';
};

const ordemToForm = (ordem) => ({
    status: ordem.status || 'Pendente',
    dataCriacao: toDateInput(ordem.createdAt),
    dataEmAndamento: toDateInput(ordem.dataEmAndamento),
    dataConclusao: toDateInput(ordem.dataConclusao),
    dataSla: toDateInput(ordem.dataSla),
    dataTrabalho: toDateInput(ordem.dataTrabalho),
    funcionarioResponsavel: ordem.funcionarioResponsavel || '',
    observacoes: ordem.observacoes || '',
    ocorrencia: ordem.ocorrencia || '',
    nomeCidadao: ordem.nomeCidadao || '',
    nomeSolicitante: ordem.nomeSolicitante || '',
    nomePropriedade: ordem.nomePropriedade || '',
    tipoMaterial: ordem.tipoMaterial || '',
    porteAnimal: ordem.porteAnimal || '',
    tipoServico: ordem.tipoServicoDetalhe || '',
    secretaria: ordem.secretaria || '',
    departamento: ordem.departamento || '',
    cep: ordem.endereco?.cep || '',
    rua: ordem.endereco?.rua || '',
    numero: ordem.endereco?.numero || '',
    bairro: ordem.endereco?.bairro || '',
    endereco: ordem.endereco?.texto || '',
    enderecoColeta: ordem.endereco?.texto || '',
    enderecoUpa: ordem.endereco?.texto || '',
    numeroOs: ordem.numero || '',
});

const formToPayload = (serviceType, formData) => ({
    tipo: serviceType,
    status: formData.status || 'Pendente',
    funcionarioResponsavel: formData.funcionarioResponsavel,
    dataSla: formData.dataSla || undefined,
    dataTrabalho: formData.dataTrabalho || undefined,
    observacoes: formData.observacoes,
    ocorrencia: formData.ocorrencia,
    nomeCidadao: formData.nomeCidadao,
    nomeSolicitante: formData.nomeSolicitante,
    nomePropriedade: formData.nomePropriedade,
    tipoMaterial: formData.tipoMaterial,
    porteAnimal: formData.porteAnimal,
    tipoServicoDetalhe: formData.tipoServico,
    secretaria: formData.secretaria,
    departamento: formData.departamento,
    endereco: {
        cep: formData.cep,
        rua: formData.rua,
        numero: formData.numero,
        bairro: formData.bairro,
        texto: formData[addressFieldForType(serviceType)] || formData.endereco || '',
    },
});

const ServiceForm = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const isEditMode = !!id;

    const [serviceType, setServiceType] = useState(SERVICE_TYPES[0]);
    const [formData, setFormData] = useState({
        status: 'Pendente',
        dataCriacao: new Date().toISOString().split('T')[0],
    });
    const [loading, setLoading] = useState(false);
    const [showAddressDetails, setShowAddressDetails] = useState(false);

    useEffect(() => {
        const fetchCep = async () => {
            const cep = formData.cep?.replace(/\D/g, '');
            if (cep?.length === 8) {
                try {
                    const response = await fetch(`https://viacep.com.br/ws/${cep}/json/`);
                    const data = await response.json();
                    if (!data.erro) {
                        const addrField = addressFieldForType(serviceType);
                        setFormData((prev) => ({
                            ...prev,
                            rua: data.logradouro,
                            bairro: data.bairro,
                            [addrField]: `${data.logradouro}, ${prev.numero || ''} - ${data.bairro}`,
                        }));
                    }
                } catch (error) {
                    console.error('Erro ao buscar CEP:', error);
                }
            }
        };
        fetchCep();
    }, [formData.cep, serviceType]);

    const handleAddressFieldChange = (e) => {
        const { name, value } = e.target;
        const updatedData = { ...formData, [name]: value };
        if (['rua', 'numero', 'bairro'].includes(name)) {
            const addrField = addressFieldForType(serviceType);
            updatedData[addrField] = `${updatedData.rua || ''}, ${updatedData.numero || ''} - ${updatedData.bairro || ''}`;
        }
        setFormData(updatedData);
    };

    useEffect(() => {
        if (!isEditMode) return;
        setLoading(true);
        api.get(`/ordens-servico/${id}`)
            .then(({ data }) => {
                if (!data?.ordem) {
                    alert('Não foi possível carregar a ordem de serviço.');
                    navigate('/');
                    return;
                }
                setServiceType(data.ordem.tipo);
                setFormData(ordemToForm(data.ordem));
            })
            .catch(() => alert('Erro ao carregar ordem de serviço.'))
            .finally(() => setLoading(false));
    }, [id, isEditMode, navigate]);

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        if (name === 'cep') {
            setFormData((prev) => ({ ...prev, [name]: value.replace(/\D/g, '').substring(0, 8) }));
            return;
        }
        if (name === 'status') {
            const today = new Date().toISOString().split('T')[0];
            const updatedData = { ...formData, status: value };
            if (value === 'Andamento' && !updatedData.dataEmAndamento) updatedData.dataEmAndamento = today;
            if (value === 'Concluído' && !updatedData.dataConclusao) updatedData.dataConclusao = today;
            setFormData(updatedData);
            return;
        }
        setFormData({ ...formData, [name]: value });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        const payload = formToPayload(serviceType, formData);
        try {
            if (isEditMode) {
                await api.patch(`/ordens-servico/${id}`, payload);
                alert('Ordem de serviço atualizada com sucesso!');
            } else {
                await api.post('/ordens-servico', payload);
                alert('Ordem de serviço cadastrada com sucesso!');
            }
            navigate('/');
        } catch (err) {
            alert(err.response?.data?.message || 'Erro ao salvar ordem de serviço');
        } finally {
            setLoading(false);
        }
    };

    const currentFields = FIELDS_SCHEMA[serviceType] || [];

    return (
        <div className="form-container page-content fade-in">
            <div className="page-header">
                <h2>{isEditMode ? 'Editar Ordem de Serviço' : 'Nova Ordem de Serviço'}</h2>
                <button onClick={() => navigate(-1)} className="btn btn-secondary">Voltar</button>
            </div>

            <div className="data-card" style={{ maxWidth: '800px', margin: '0 auto' }}>
                {loading && <p>Carregando...</p>}
                {!loading && (
                    <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '1.2rem' }}>
                        {isEditMode && formData.numeroOs && (
                            <p style={{ color: 'var(--text-secondary)' }}>Número: <strong>{formData.numeroOs}</strong></p>
                        )}
                        <div className="input-group">
                            <label>Módulo / Tipo de Serviço</label>
                            <select
                                className="input-field"
                                value={serviceType}
                                onChange={(e) => {
                                    setServiceType(e.target.value);
                                    if (!isEditMode) setFormData({ status: 'Pendente', dataTrabalho: new Date().toISOString().split('T')[0] });
                                }}
                                disabled={isEditMode}
                            >
                                {SERVICE_TYPES.map((type) => <option key={type} value={type}>{type}</option>)}
                            </select>
                        </div>

                        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1.2rem' }}>
                            {currentFields.map((field) => {
                                if (field === 'observacoes' || field === 'ocorrencia' || field === 'dataTrabalho') return null;

                                if (field === 'status') {
                                    return (
                                        <div className="input-group" key={field}>
                                            <label>{FIELD_LABELS[field]}</label>
                                            <div style={{ display: 'flex', gap: '0.5rem' }}>
                                                <select className="input-field" name={field} value={formData[field] || ''} onChange={handleInputChange} style={{ flex: 1 }}>
                                                    <option value="Pendente">Pendente</option>
                                                    <option value="Andamento">Andamento</option>
                                                    <option value="Concluído">Concluído</option>
                                                </select>
                                                {currentFields.includes('dataTrabalho') && (
                                                    <input type="date" className="input-field" name="dataTrabalho" value={formData.dataTrabalho || ''} onChange={handleInputChange} style={{ flex: 1 }} />
                                                )}
                                            </div>
                                        </div>
                                    );
                                }

                                if (field === 'secretaria') {
                                    return (
                                        <div className="input-group" key={field}>
                                            <label>{FIELD_LABELS[field]}</label>
                                            <select className="input-field" name={field} value={formData[field] || ''} onChange={handleInputChange}>
                                                <option value="">Selecione...</option>
                                                {SECRETARIAS.map((s) => <option key={s} value={s}>{s}</option>)}
                                            </select>
                                        </div>
                                    );
                                }

                                if (field === 'dataSla') {
                                    return (
                                        <div className="input-group" key={field}>
                                            <label>{FIELD_LABELS[field]}</label>
                                            <input type="date" className="input-field" name={field} value={formData[field] || ''} onChange={handleInputChange} />
                                        </div>
                                    );
                                }

                                const isAddressField = field === 'enderecoColeta' || field === 'endereco' || field === 'enderecoUpa';
                                const needsDetailedAddress = ['Coleta de Inservíveis', 'Coleta de Animais Mortos', 'Coleta de Galhos', 'Manutenção de Praças', 'Manutenção de Escolas Estaduais', 'Manutenção de Vias Rurais'].includes(serviceType);

                                if (isAddressField && needsDetailedAddress) {
                                    return (
                                        <div className="input-group" key={field} style={{ gridColumn: 'span 2' }}>
                                            <label>{FIELD_LABELS[field]}</label>
                                            {!showAddressDetails ? (
                                                <input
                                                    type="text"
                                                    className="input-field"
                                                    name={field}
                                                    placeholder="Clique para preencher endereço detalhado ou digite aqui..."
                                                    value={formData[field] || ''}
                                                    onChange={handleInputChange}
                                                    onClick={() => setShowAddressDetails(true)}
                                                />
                                            ) : (
                                                <div style={{ display: 'grid', gridTemplateColumns: '1fr 2fr 1fr 2fr', gap: '0.8rem', padding: '1rem', backgroundColor: '#f9fafb', borderRadius: 'var(--radius-md)', border: '1px solid #e5e7eb' }}>
                                                    <div className="input-group" style={{ marginBottom: 0 }}>
                                                        <label style={{ fontSize: '0.75rem' }}>CEP</label>
                                                        <input type="text" name="cep" className="input-field" value={formData.cep || ''} onChange={handleInputChange} placeholder="00000-000" />
                                                    </div>
                                                    <div className="input-group" style={{ marginBottom: 0 }}>
                                                        <label style={{ fontSize: '0.75rem' }}>Rua</label>
                                                        <input type="text" name="rua" className="input-field" value={formData.rua || ''} onChange={handleAddressFieldChange} />
                                                    </div>
                                                    <div className="input-group" style={{ marginBottom: 0 }}>
                                                        <label style={{ fontSize: '0.75rem' }}>Nº</label>
                                                        <input type="text" name="numero" className="input-field" value={formData.numero || ''} onChange={handleAddressFieldChange} />
                                                    </div>
                                                    <div className="input-group" style={{ marginBottom: 0 }}>
                                                        <label style={{ fontSize: '0.75rem' }}>Bairro</label>
                                                        <input type="text" name="bairro" className="input-field" value={formData.bairro || ''} onChange={handleAddressFieldChange} />
                                                    </div>
                                                    <button type="button" className="btn btn-secondary" style={{ gridColumn: 'span 4', fontSize: '0.8rem', padding: '0.3rem' }} onClick={() => setShowAddressDetails(false)}>
                                                        Recolher Detalhes
                                                    </button>
                                                </div>
                                            )}
                                        </div>
                                    );
                                }

                                return (
                                    <div className="input-group" key={field}>
                                        <label>{FIELD_LABELS[field]}</label>
                                        <input type="text" className="input-field" name={field} value={formData[field] || ''} onChange={handleInputChange} required={field === 'funcionarioResponsavel'} />
                                    </div>
                                );
                            })}
                        </div>

                        {currentFields.includes('observacoes') && (
                            <div className="input-group">
                                <label>{FIELD_LABELS.observacoes}</label>
                                <textarea className="input-field" name="observacoes" rows="3" value={formData.observacoes || ''} onChange={handleInputChange}></textarea>
                            </div>
                        )}

                        {currentFields.includes('ocorrencia') && (
                            <div className="input-group">
                                <label>{FIELD_LABELS.ocorrencia} (Opcional)</label>
                                <textarea className="input-field" name="ocorrencia" rows="3" value={formData.ocorrencia || ''} onChange={handleInputChange}></textarea>
                            </div>
                        )}

                        {isEditMode && (
                            <div style={{ marginTop: '1rem', padding: '1rem', backgroundColor: 'var(--surface-color)', borderRadius: 'var(--radius-md)', border: '1px solid var(--border-color)' }}>
                                <h4 style={{ marginBottom: '0.5rem', fontSize: '0.9rem', color: 'var(--text-secondary)' }}>Histórico de Datas (Automático)</h4>
                                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))', gap: '1rem', fontSize: '0.85rem' }}>
                                    <div><strong>Criado em:</strong> {formatDate(formData.dataCriacao)}</div>
                                    <div><strong>Andamento:</strong> {formatDate(formData.dataEmAndamento)}</div>
                                    <div><strong>Concluído:</strong> {formatDate(formData.dataConclusao)}</div>
                                </div>
                            </div>
                        )}

                        <button type="submit" className="btn" style={{ marginTop: '1rem', backgroundColor: 'var(--secondary-color)', color: 'white' }}>
                            {isEditMode ? 'Atualizar Ordem' : 'Salvar Ordem'}
                        </button>
                    </form>
                )}
            </div>
        </div>
    );
};

export default ServiceForm;
