import React, { createContext, useContext, useState, useEffect } from 'react';
import api, { readToken } from '../utils/api';

const AuthContext = createContext();

function normalizeUser(data) {
    if (!data) return null;
    const src = data.user || data;
    return {
        _id: src._id || src.id || data.userId,
        name: src.name || data.name,
        email: src.email || data.email,
        role: src.role || data.role,
        isAdmin: !!(src.isAdmin || data.isAdmin),
    };
}

function canAccessModule(user) {
    if (!user) return false;
    if (user.isAdmin) return true;
    const role = String(user.role || '').toLowerCase();
    return role === 'admin' || role === 'smsu';
}

export const AuthProvider = ({ children }) => {
    const [authenticated, setAuthenticated] = useState(false);
    const [loading, setLoading] = useState(true);
    const [user, setUser] = useState(null);

    useEffect(() => {
        const bootstrap = async () => {
            const token = readToken();
            if (!token) {
                setLoading(false);
                return;
            }
            try {
                const { data } = await api.get('/users/checkuser');
                const nextUser = normalizeUser(data);
                if (!nextUser || !canAccessModule(nextUser)) {
                    logout();
                    setLoading(false);
                    return;
                }
                setUser(nextUser);
                setAuthenticated(true);
            } catch (_err) {
                logout();
            } finally {
                setLoading(false);
            }
        };
        bootstrap();
    }, []);

    async function login(credentials) {
        try {
            const { data } = await api.post('/users/login', credentials);
            const token = data.token || data.accessToken;
            if (!token) {
                return { success: false, message: 'Resposta de login inválida.' };
            }
            localStorage.setItem('token', token);
            if (data.refreshToken) {
                localStorage.setItem('memorial_refresh', data.refreshToken);
            }

            let nextUser = normalizeUser(data);
            try {
                const check = await api.get('/users/checkuser');
                nextUser = normalizeUser(check.data) || nextUser;
            } catch (_err) {
                // keep user from login payload
            }

            if (!canAccessModule(nextUser)) {
                logout();
                return {
                    success: false,
                    message: 'Sem permissão para o Sistema de Ordem de Serviços. Solicite o perfil SMSU à SEMIT.',
                };
            }

            setUser(nextUser);
            setAuthenticated(true);
            return { success: true, message: data.message };
        } catch (error) {
            const message = error.response?.data?.message || error.message || 'Erro ao fazer login';
            return { success: false, message: typeof message === 'string' ? message : 'Erro inesperado no servidor' };
        }
    }

    function logout() {
        setAuthenticated(false);
        setUser(null);
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        localStorage.removeItem('memorial_refresh');
        api.defaults.headers.Authorization = undefined;
    }

    return (
        <AuthContext.Provider value={{ authenticated, loading, login, logout, user }}>
            {children}
        </AuthContext.Provider>
    );
};

export const useAuth = () => useContext(AuthContext);
