import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { formatDate, locationLabel } from './utils';

export function generateOrdemServicoPdf({ ordens, userName }) {
    const doc = new jsPDF();
    const now = new Date();
    const brandBlue = [1, 72, 152];
    const list = Array.isArray(ordens) ? ordens : [];

    const loadImg = (url) => new Promise((resolve) => {
        const img = new Image();
        img.src = url;
        img.onload = () => resolve(img);
        img.onerror = () => resolve(null);
    });

    const buildPDFBody = () => {
        doc.setDrawColor(200, 200, 200);
        doc.line(14, 32, 196, 32);

        const addSectionHeader = (title, y) => {
            doc.setFillColor(...brandBlue);
            doc.rect(14, y, 182, 8, 'F');
            doc.setFontSize(12);
            doc.setFont('helvetica', 'bold');
            doc.setTextColor(255, 255, 255);
            doc.text(title, 18, y + 6);
            doc.setTextColor(0, 0, 0);
            doc.setFont('helvetica', 'normal');
            return y + 15;
        };

        const total = list.length;
        const demandByArea = {};
        const employeeStats = {};

        list.forEach((os) => {
            const area = os.endereco?.bairro || 'Não Informado';
            demandByArea[area] = (demandByArea[area] || 0) + 1;
            const emp = os.funcionarioResponsavel || 'Não Informado';
            if (!employeeStats[emp]) employeeStats[emp] = { total: 0, onTime: 0 };
            employeeStats[emp].total += 1;
            if (os.status === 'Concluído' && os.dataConclusao && os.dataSla && new Date(os.dataConclusao) <= new Date(os.dataSla)) {
                employeeStats[emp].onTime += 1;
            }
        });

        const topArea = Object.entries(demandByArea).sort((a, b) => b[1] - a[1])[0] || ['N/A', 0];
        const topEmployee = Object.entries(employeeStats).sort((a, b) => b[1].total - a[1].total)[0] || ['N/A', { total: 0, onTime: 0 }];
        const concluded = list.filter((os) => os.status === 'Concluído');
        const onTime = concluded.filter((os) => os.dataConclusao && os.dataSla && new Date(os.dataConclusao) <= new Date(os.dataSla)).length;
        const delayed = concluded.length - onTime;
        const onTimePct = concluded.length > 0 ? ((onTime / concluded.length) * 100).toFixed(1) : 0;

        let currentY = 40;
        currentY = addSectionHeader('1. Identificação', currentY);
        doc.setFontSize(10);
        doc.text('Sistema: Ordem de Serviços Urbanos (SMSU)', 14, currentY);
        doc.text(`Período analisado: registros filtrados até ${now.toLocaleDateString('pt-BR')}`, 14, currentY + 5);
        doc.text(`Responsável pela geração: ${userName || 'Administrador'}`, 14, currentY + 10);

        currentY += 25;
        currentY = addSectionHeader('2. Resumo Geral (Visão Rápida)', currentY);
        doc.text(`• Total de ordens no recorte: ${total}`, 14, currentY);
        doc.text(`• Situação geral: ${onTimePct > 70 ? 'Satisfatória (Maioria no prazo)' : 'Alerta (Atenção aos prazos)'}`, 14, currentY + 5);
        doc.text(`• Destaque principal: ${list[0]?.tipo || 'ordens de serviço'}.`, 14, currentY + 10);

        currentY += 25;
        currentY = addSectionHeader('3. Demanda de Serviços', currentY);
        doc.text(`• Total de solicitações: ${total}`, 14, currentY);
        doc.setFont('helvetica', 'bold');
        doc.text(`• Área com maior demanda: ${topArea[0]} (${topArea[1]} atendimentos)`, 14, currentY + 5);
        doc.setFont('helvetica', 'normal');

        currentY += 20;
        currentY = addSectionHeader('4. Desempenho dos Funcionários', currentY);
        doc.text(`• Funcionário mais ativo: ${topEmployee[0]}`, 14, currentY);
        doc.text(`• Ordens realizadas por ele: ${topEmployee[1].total}`, 14, currentY + 5);
        doc.text(`• Taxa de entrega no prazo (do funcionário): ${topEmployee[1].total > 0 ? ((topEmployee[1].onTime / topEmployee[1].total) * 100).toFixed(1) : 0}%`, 14, currentY + 10);

        currentY += 25;
        currentY = addSectionHeader('5. Prazos de Atendimento', currentY);
        doc.text(`• Ordens concluídas dentro do prazo: ${onTime} (${onTimePct}%)`, 14, currentY);
        doc.text(`• Ordens com atraso: ${delayed} (${concluded.length > 0 ? (100 - Number(onTimePct)).toFixed(1) : 0}%)`, 14, currentY + 5);

        currentY += 20;
        currentY = addSectionHeader('6. Análise dos Resultados', currentY);
        doc.setFontSize(9);
        doc.text('Interpretação dos dados coletados:', 14, currentY);
        doc.text([
            `• Atrasos identificados: ${delayed > 0 ? 'Fatores externos ou alta demanda pontual.' : 'Nenhum atraso crítico identificado.'}`,
            `• O aumento de demanda em ${topArea[0]} exige atenção no deslocamento da equipe.`,
            `• Conclusão técnica: ${onTimePct > 50 ? 'A equipe está absorvendo bem a carga.' : 'Necessário revisão de processos para reduzir gargalos.'}`,
        ], 14, currentY + 5);

        currentY += 30;
        currentY = addSectionHeader('7. Conclusão', currentY);
        doc.setFontSize(10);
        doc.text('Resumo final e visão geral:', 14, currentY);
        doc.setFont('helvetica', 'italic');
        doc.text(`O recorte opera com ${total} ordens, apresentando eficiência de ${onTimePct}% nos prazos.`, 14, currentY + 5);
        doc.text('Recomenda-se manter o monitoramento contínuo das áreas de maior demanda.', 14, currentY + 10);

        doc.addPage();
        doc.setFont('helvetica', 'bold');
        doc.setFontSize(14);
        doc.text('Anexo: Listagem Detalhada de Ordens de Serviço', 14, 20);

        autoTable(doc, {
            startY: 25,
            head: [['Data', 'Tipo', 'Nº', 'Responsável', 'Localização', 'Status']],
            body: list.map((os) => [
                formatDate(os.createdAt),
                os.tipo,
                os.numero || '-',
                os.funcionarioResponsavel || 'N/A',
                locationLabel(os),
                os.status || 'Pendente',
            ]),
            theme: 'striped',
            headStyles: { fillColor: brandBlue },
            styles: { fontSize: 8 },
        });

        doc.save(`Ordem_Servicos_${now.toISOString().split('T')[0]}.pdf`);
    };

    const brasaoUrl = `${process.env.PUBLIC_URL || ''}/assets/brasao.png`;
    loadImg(brasaoUrl).then((imgBrasao) => {
        doc.setFont('helvetica', 'bold');
        doc.setFontSize(14);
        doc.setTextColor(60, 60, 60);
        doc.text('Prefeitura Municipal de Garça', 105, 15, { align: 'center' });
        doc.setFontSize(12);
        doc.setFont('helvetica', 'normal');
        doc.text('Secretaria Municipal de Serviços Urbanos', 105, 23, { align: 'center' });
        doc.setFontSize(10);
        doc.text('Garça/SP', 105, 29, { align: 'center' });
        if (imgBrasao) {
            doc.addImage(imgBrasao, 'PNG', 14, 8, 22, 22);
        }
        buildPDFBody();
    });
}
