export const formatDate = (date) => {
    if (!date) return '-';
    return new Date(date).toLocaleDateString('pt-BR');
};

export const formatMonthYear = (date) => {
    if (!date) return '-';
    return new Date(date).toLocaleString('pt-BR', { month: 'short', year: 'numeric' });
};

export const toDateInput = (value) => {
    if (!value) return '';
    const raw = String(value);
    if (/^\d{4}-\d{2}-\d{2}$/.test(raw.slice(0, 10))) return raw.slice(0, 10);
    const d = new Date(value);
    if (Number.isNaN(d.getTime())) return '';
    return d.toISOString().slice(0, 10);
};

export const addressText = (ordem) => {
    if (!ordem) return '';
    return ordem.endereco?.texto || ordem.secretaria || '';
};

export const locationLabel = (ordem) => {
    if (!ordem) return 'N/A';
    return ordem.endereco?.bairro || ordem.endereco?.texto || ordem.secretaria || 'N/A';
};

export const personLabel = (ordem) => {
    if (!ordem) return 'Não Aplicável';
    return ordem.funcionarioResponsavel || ordem.nomeCidadao || ordem.nomeSolicitante || ordem.nomePropriedade || 'Não Aplicável';
};
