import { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import api from '../../utils/api';
import { formatDate, addressText, personLabel, toDateInput } from '../../utils/utils';
import { generateOrdemServicoPdf } from '../../utils/pdfOrdemServico';
import { useAuth } from '../../context/AuthContext';
import { FaFilePdf } from 'react-icons/fa';

const TIPOS_OS = [
    'Coleta de Inservíveis',
    'Coleta de Animais Mortos',
    'Manutenção de Vias Rurais',
    'Coleta de Galhos',
    'Manutenção de Praças',
    'Manutenção de Escolas Estaduais',
    'Prestação de Serviço às Demais Secretarias',
    'Caminhão Pipa',
];

const Home = () => {
    const { user } = useAuth();
    const navigate = useNavigate();
    const [ordens, setOrdens] = useState([]);
    const [loading, setLoading] = useState(true);
    const [filterTipo, setFilterTipo] = useState('');
    const [filterStatus, setFilterStatus] = useState('');
    const [filterDataInicio, setFilterDataInicio] = useState('');
    const [filterDataFim, setFilterDataFim] = useState('');
    const [filterFuncionario, setFilterFuncionario] = useState('');

    const fetchOrdens = async () => {
        try {
            const params = {};
            if (filterTipo) params.tipo = filterTipo;
            if (filterStatus) params.status = filterStatus;
            else params.incluirConcluidos = 'false';
            if (filterDataInicio) params.dataInicio = filterDataInicio;
            if (filterDataFim) params.dataFim = filterDataFim;
            if (filterFuncionario) params.funcionario = filterFuncionario;
            const { data } = await api.get('/ordens-servico', { params });
            setOrdens(Array.isArray(data.ordens) ? data.ordens : []);
        } catch (error) {
            console.error('Failed to fetch ordens', error);
            setOrdens([]);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchOrdens();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [filterTipo, filterStatus, filterDataInicio, filterDataFim, filterFuncionario]);

    const handleStatusChange = async (id, newStatus) => {
        try {
            await api.patch(`/ordens-servico/${id}/status`, { status: newStatus });
            fetchOrdens();
        } catch (_error) {
            alert('Erro ao atualizar status.');
        }
    };

    const uniqueTipos = TIPOS_OS;

    return (
        <div className="home-container page-content fade-in">
            <div className="page-header">
                <h2>Ordens de Serviço</h2>
                <div style={{ display: 'flex', gap: '1rem' }}>
                    <button onClick={() => generateOrdemServicoPdf({ ordens, userName: user?.name })} className="btn btn-primary" style={{ backgroundColor: '#10b981' }}>
                        <FaFilePdf style={{ marginRight: '8px' }} />
                        Imprimir Relatório
                    </button>
                    <button onClick={() => navigate('/create-service')} className="btn btn-primary">Nova Ordem</button>
                </div>
            </div>

            <div className="data-card filters-section" style={{ marginBottom: '2rem' }}>
                <h4 style={{ marginBottom: '1rem' }}>Filtros de Busca</h4>
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '1rem' }}>
                    <div className="input-group">
                        <label>Tipo de Serviço</label>
                        <select className="input-field" value={filterTipo} onChange={(e) => setFilterTipo(e.target.value)}>
                            <option value="">Todos</option>
                            {uniqueTipos.map((t) => <option key={t} value={t}>{t}</option>)}
                        </select>
                    </div>
                    <div className="input-group">
                        <label>Status</label>
                        <select className="input-field" value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)}>
                            <option value="">Abertas</option>
                            <option value="Pendente">Pendente</option>
                            <option value="Andamento">Andamento</option>
                            <option value="Concluído">Concluído</option>
                        </select>
                    </div>
                    <div className="input-group">
                        <label>Data Início</label>
                        <input type="date" className="input-field" value={filterDataInicio} onChange={(e) => setFilterDataInicio(e.target.value)} />
                    </div>
                    <div className="input-group">
                        <label>Data Fim</label>
                        <input type="date" className="input-field" value={filterDataFim} onChange={(e) => setFilterDataFim(e.target.value)} />
                    </div>
                    <div className="input-group">
                        <label>Funcionário Responsável</label>
                        <input type="text" className="input-field" placeholder="Buscar nome..." value={filterFuncionario} onChange={(e) => setFilterFuncionario(e.target.value)} />
                    </div>
                </div>
            </div>

            <div className="data-card">
                {loading ? (
                    <p>Carregando ordens...</p>
                ) : ordens.length === 0 ? (
                    <p>Nenhuma ordem de serviço encontrada.</p>
                ) : (
                    <div className="table-responsive" style={{ overflowX: 'auto' }}>
                        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
                            <thead>
                                <tr style={{ borderBottom: '2px solid #e5e7eb' }}>
                                    <th style={{ padding: '1rem 0.5rem', color: 'var(--primary-color)' }}>Data</th>
                                    <th style={{ padding: '1rem 0.5rem', color: 'var(--primary-color)' }}>Serviço</th>
                                    <th style={{ padding: '1rem 0.5rem', color: 'var(--primary-color)' }}>Funcionário/Local</th>
                                    <th style={{ padding: '1rem 0.5rem', color: 'var(--primary-color)' }}>Prazo</th>
                                    <th style={{ padding: '1rem 0.5rem', color: 'var(--primary-color)' }}>Status</th>
                                    <th style={{ padding: '1rem 0.5rem', color: 'var(--primary-color)' }}>Ações</th>
                                </tr>
                            </thead>
                            <tbody>
                                {ordens.map((os) => {
                                    const status = os.status || 'Pendente';
                                    let prazoStyle = { color: 'var(--text-secondary)' };
                                    let prazoText = os.dataSla ? formatDate(os.dataSla) : 'Sem prazo';

                                    if (os.dataSla && status !== 'Concluído') {
                                        const today = new Date();
                                        today.setHours(0, 0, 0, 0);
                                        const prazoDate = new Date(toDateInput(os.dataSla) + 'T00:00:00');
                                        if (prazoDate < today) {
                                            prazoStyle = { color: '#b91c1c', backgroundColor: '#fca5a5', padding: '0.2rem 0.5rem', borderRadius: '4px', fontWeight: 'bold' };
                                        } else if (prazoDate.getTime() === today.getTime()) {
                                            prazoStyle = { color: '#b45309', backgroundColor: '#fde68a', padding: '0.2rem 0.5rem', borderRadius: '4px', fontWeight: 'bold' };
                                        } else {
                                            prazoStyle = { color: '#15803d', backgroundColor: '#bbf7d0', padding: '0.2rem 0.5rem', borderRadius: '4px', fontWeight: 'bold' };
                                        }
                                    }

                                    return (
                                        <tr key={os._id} style={{ borderBottom: '1px solid var(--border-color)' }}>
                                            <td style={{ padding: '1rem 0.5rem' }}>{formatDate(os.createdAt)}</td>
                                            <td style={{ padding: '1rem 0.5rem' }}>
                                                <strong style={{ color: 'var(--primary-color)' }}>{os.tipo}</strong>
                                                <div style={{ fontSize: '0.8em', color: 'var(--text-secondary)' }}>{os.numero}</div>
                                            </td>
                                            <td style={{ padding: '1rem 0.5rem' }}>
                                                {personLabel(os)}
                                                <div style={{ fontSize: '0.85em', color: 'var(--text-secondary)' }}>{addressText(os)}</div>
                                            </td>
                                            <td style={{ padding: '1rem 0.5rem' }}>
                                                <span style={prazoStyle}>{prazoText}</span>
                                            </td>
                                            <td style={{ padding: '1rem 0.5rem' }}>
                                                <select
                                                    style={{
                                                        padding: '0.25rem 0.5rem',
                                                        borderRadius: 'var(--radius-sm)',
                                                        fontSize: '0.85rem',
                                                        fontWeight: '600',
                                                        border: '1px solid currentColor',
                                                        cursor: 'pointer',
                                                        backgroundColor: status === 'Concluído' ? '#d1fae5' : status === 'Andamento' ? '#dbeafe' : '#fff7ed',
                                                        color: status === 'Concluído' ? '#065f46' : status === 'Andamento' ? '#1e40af' : '#c2410c',
                                                    }}
                                                    value={status}
                                                    onChange={(e) => handleStatusChange(os._id, e.target.value)}
                                                >
                                                    <option value="Pendente">Pendente</option>
                                                    <option value="Andamento">Andamento</option>
                                                    <option value="Concluído">Concluído</option>
                                                </select>
                                            </td>
                                            <td style={{ padding: '1rem 0.5rem' }}>
                                                <Link to={`/edit-service/${os._id}`} className="btn" style={{ padding: '0.4rem 0.75rem', fontSize: '0.875rem', backgroundColor: 'var(--secondary-color)', color: 'white' }}>
                                                    Visualizar / Editar
                                                </Link>
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>
        </div>
    );
};

export default Home;
