import React, { useState, useEffect } from 'react';
import api from '../../utils/api';
import { formatMonthYear } from '../../utils/utils';
import {
    BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
    PieChart, Pie, Cell, LineChart, Line,
} from 'recharts';

const STATUS_COLORS = {
    '1. Pendente': '#f59e0b',
    '2. Andamento': '#3b82f6',
    '3. Concluído': '#10b981',
};

const COLORS = ['#f59e0b', '#3b82f6', '#10b981', '#ef4444', '#8b5cf6', '#ec4899'];

const DashboardMetrics = () => {
    const [ordens, setOrdens] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchOrdens = async () => {
            try {
                const { data } = await api.get('/ordens-servico', { params: { incluirConcluidos: 'true', status: 'all' } });
                setOrdens(Array.isArray(data.ordens) ? data.ordens : []);
            } catch (error) {
                console.error('Failed to fetch ordens', error);
                setOrdens([]);
            } finally {
                setLoading(false);
            }
        };
        fetchOrdens();
    }, []);

    const statusCount = { Pendente: 0, Andamento: 0, Concluído: 0 };
    const typeCount = {};
    const completedByMonth = {};
    const funcCount = {};

    ordens.forEach((os) => {
        const status = (os.status || 'Pendente').trim();
        if (statusCount[status] !== undefined) statusCount[status] += 1;
        typeCount[os.tipo] = (typeCount[os.tipo] || 0) + 1;
        const func = os.funcionarioResponsavel || 'Não Atribuído';
        funcCount[func] = (funcCount[func] || 0) + 1;
        if (status === 'Concluído') {
            const month = formatMonthYear(os.dataConclusao || os.createdAt);
            completedByMonth[month] = (completedByMonth[month] || 0) + 1;
        }
    });

    const statusData = [
        { name: '1. Pendente', value: statusCount.Pendente },
        { name: '2. Andamento', value: statusCount.Andamento },
        { name: '3. Concluído', value: statusCount.Concluído },
    ];
    const typeData = Object.keys(typeCount).map((key) => ({ name: key, quantidade: typeCount[key] }));
    const funcData = Object.keys(funcCount)
        .map((key) => ({ name: key, quantidade: funcCount[key] }))
        .sort((a, b) => b.quantidade - a.quantidade)
        .slice(0, 10);
    const timelineData = Object.keys(completedByMonth)
        .map((key) => ({ month: key, concluidos: completedByMonth[key] }))
        .sort((a, b) => a.month.localeCompare(b.month, 'pt-BR'));

    if (loading) return <div className="page-content"><p>Carregando métricas...</p></div>;

    return (
        <div className="metrics-container page-content fade-in">
            <div className="page-header">
                <h2>Ordens de Serviço / Dashboard</h2>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(400px, 1fr))', gap: '2rem' }}>
                <div className="data-card">
                    <h4 style={{ marginBottom: '1rem', color: 'var(--text-secondary)' }}>Quantidade de Ordens por Status</h4>
                    <div style={{ height: 300 }}>
                        <ResponsiveContainer width="100%" height="100%">
                            <PieChart>
                                <Pie
                                    data={statusData}
                                    cx="50%"
                                    cy="50%"
                                    outerRadius={100}
                                    fill="#8884d8"
                                    dataKey="value"
                                    label={({ name, percent }) => `${name.split('. ')[1]} ${(percent * 100).toFixed(0)}%`}
                                >
                                    {statusData.map((entry, index) => (
                                        <Cell key={`cell-${index}`} fill={STATUS_COLORS[entry.name] || COLORS[index % COLORS.length]} />
                                    ))}
                                </Pie>
                                <Tooltip />
                                <Legend iconType="square" verticalAlign="bottom" align="center" formatter={(value) => value.split('. ')[1]} />
                            </PieChart>
                        </ResponsiveContainer>
                    </div>
                </div>

                <div className="data-card">
                    <h4 style={{ marginBottom: '1rem', color: 'var(--text-secondary)' }}>Quantidade por Tipo de Serviço</h4>
                    <div style={{ height: 300 }}>
                        <ResponsiveContainer width="100%" height="100%">
                            <BarChart data={typeData} layout="vertical" margin={{ left: 50 }}>
                                <CartesianGrid strokeDasharray="3 3" />
                                <XAxis type="number" />
                                <YAxis dataKey="name" type="category" width={120} tick={{ fontSize: 12 }} />
                                <Tooltip />
                                <Bar dataKey="quantidade" fill="var(--primary-color)" />
                            </BarChart>
                        </ResponsiveContainer>
                    </div>
                </div>

                <div className="data-card">
                    <h4 style={{ marginBottom: '1rem', color: 'var(--text-secondary)' }}>Ordens Concluídas por Período</h4>
                    <div style={{ height: 300 }}>
                        <ResponsiveContainer width="100%" height="100%">
                            <LineChart data={timelineData}>
                                <CartesianGrid strokeDasharray="3 3" />
                                <XAxis dataKey="month" />
                                <YAxis />
                                <Tooltip />
                                <Legend />
                                <Line type="monotone" dataKey="concluidos" stroke="var(--secondary-color)" strokeWidth={3} />
                            </LineChart>
                        </ResponsiveContainer>
                    </div>
                </div>

                <div className="data-card">
                    <h4 style={{ marginBottom: '1rem', color: 'var(--text-secondary)' }}>Ordens por Funcionário (Top 10)</h4>
                    <div style={{ height: 300 }}>
                        <ResponsiveContainer width="100%" height="100%">
                            <BarChart data={funcData}>
                                <CartesianGrid strokeDasharray="3 3" />
                                <XAxis dataKey="name" tick={{ fontSize: 12 }} />
                                <YAxis />
                                <Tooltip />
                                <Bar dataKey="quantidade" fill="#8b5cf6" />
                            </BarChart>
                        </ResponsiveContainer>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default DashboardMetrics;
