import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider, useAuth } from './context/AuthContext';

import Login from './pages/Auth/Login';
import DashboardLayout from './pages/Dashboard/DashboardLayout';
import Home from './pages/Dashboard/Home';
import DashboardMetrics from './pages/Dashboard/DashboardMetrics';
import ServiceForm from './pages/Dashboard/ServiceForm';

const ProtectedRoute = ({ children }) => {
    const { authenticated, loading } = useAuth();

    if (loading) {
        return <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh' }}>Carregando...</div>;
    }

    return authenticated ? children : <Navigate to="/login" replace />;
};

function App() {
    return (
        <Router basename="/ordem-servicos">
            <AuthProvider>
                <Routes>
                    <Route path="/login" element={<Login />} />
                    <Route
                        path="/"
                        element={
                            <ProtectedRoute>
                                <DashboardLayout />
                            </ProtectedRoute>
                        }
                    >
                        <Route index element={<Home />} />
                        <Route path="dashboard" element={<DashboardMetrics />} />
                        <Route path="create-service" element={<ServiceForm />} />
                        <Route path="edit-service/:id" element={<ServiceForm />} />
                    </Route>
                    <Route path="*" element={<Navigate to="/" replace />} />
                </Routes>
            </AuthProvider>
        </Router>
    );
}

export default App;
